const body = $input.first().json.body;
const fail = (error) => [{ json: { valid: false, error } }];
if (!body || typeof body !== 'object' || Array.isArray(body)) return fail('Body must be a JSON object');
if (typeof body.message !== 'string' || !body.message.trim()) return fail('message must be a non-empty string');
if (body.message.length > 2000) return fail('message must not exceed 2000 characters');
const limits = { name: 120, contact: 120, source: 80, locale: 10 };
for (const [key, limit] of Object.entries(limits)) {
  if (body[key] !== undefined && (typeof body[key] !== 'string' || body[key].length > limit)) return fail(key + ' must be a string of at most ' + limit + ' characters');
}
return [{ json: { valid: true, lead: { received_at: new Date().toISOString(), name: body.name?.trim() || 'unknown', contact: body.contact?.trim() || '', source: body.source?.trim() || 'unknown', locale: body.locale?.trim() || 'en', message: body.message.trim() } } }];

const lead = $('Validate lead').first().json.lead;
const response = $input.first().json;
let result = { intent: 'other', score: null, is_hot: false, summary_en: 'Automatic triage unavailable. Review the original message.', draft_reply: '', needs_review: true, llm_status: 'unavailable' };
if (!response.error) {
  try {
    const choice = response.choices?.[0];
    if (choice?.finish_reason !== 'stop' || choice.message?.refusal) throw new Error('Incomplete response');
    const parsed = JSON.parse(choice.message.content);
    if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) throw new Error('Invalid object');
    if (!['pricing', 'demo', 'support', 'other'].includes(parsed.intent)) throw new Error('Invalid intent');
    if (typeof parsed.score !== 'number' || !Number.isFinite(parsed.score) || parsed.score < 0 || parsed.score > 100) throw new Error('Invalid score');
    if (typeof parsed.summary_en !== 'string' || !parsed.summary_en.trim() || parsed.summary_en.length > 500) throw new Error('Invalid summary');
    if (typeof parsed.draft_reply !== 'string' || !parsed.draft_reply.trim() || parsed.draft_reply.length > 400) throw new Error('Invalid reply');
    const score = Math.round(parsed.score);
    result = { intent: parsed.intent, score, is_hot: score >= 70, summary_en: parsed.summary_en.trim(), draft_reply: parsed.draft_reply.trim(), needs_review: false, llm_status: 'ok' };
  } catch {
    result.llm_status = 'invalid_response';
  }
}
return [{ json: { ...lead, ...result } }];
